// 2025-1-15 16:04:27 1647 81 842
// 三角形递归法彭罗斯镶嵌
//
// Triangular Recursive Penrose Tiling Method
// https://tilings.math.uni-bielefeld.de/substitution/robinson-triangle/
// https://www.shadertoy.com/view/4t2XWG - @tomkh
// https://www.shadertoy.com/view/X33Bz8 - @Elsio





#define N 7
#define bdlen 5.
#define PI 3.1415926535
#define G 0.618033988749895 
#define lca length(c-a)
//#define cross2(a,b)  ((a).y*(b).x-(a).x*(b).y)

float dline(vec3 a, vec3 b, vec3 p){
        b-=a; p-=a;
        return length(p - b * clamp(dot(p,b)/dot(b,b), 0., 1.));
}

void mainImage(out vec4 o, vec2 U)
{
        vec2 R = iResolution.xy;
        vec3 u;u.xy = (U + U - R) / R.y;

        float f1,f2;
        vec3 a, b, c, d, e ,newa, newb, newc, n1, n2;
        int type;

        a = vec3(-bdlen, -1,0), 
        b = vec3(bdlen, -1,0), 
        c = vec3(0, -1.+bdlen * tan(PI/5.),0); 
        type = 1;

        for(int i=0; i<N; i++)
        {
                if(type==1)
                {// Wide triangle (or Wide rhombus)
                        d = a + (b - a) * G;// D is the golden section point on side AB.
                        e = a + (c - a) * G;// E is on side AC.
                        //n1 = (e-d).yx * vec2(-1,1);// The dividing line is DE.
                        //n2 = (c-d).yx * vec2(-1,1);// The dividing line is DC.
                        //f1 = dot(a-d, n1)*dot(u - d, n1);
                        //f2 = dot(b-d, n2)*dot(u - d, n2);

                        f1 = cross(a-d,e-d).z*cross(u-d,e-d).z;
                        f2 = cross(b-d,c-d).z*cross(u-d,c-d).z;

                        if(f1>0.){// In the triangle near point A.
                                //newa = d, newb = a, newc = e;                                
                                b=a, a=d, c=e;
                                type=1;// The input for the next recursion                        
                        }else if(f2>0.){// In the triangle near point B.
                                //newa = b, newb = c, newc = d;                         
                                a=b, b=c, c=d;
                                type=1;
                        }else{// In the triangle located in the middle.
                                //newa = e, newb = c, newc = d;                               
                                a=e, b=c, c=d;
                                type=2;
                        }
                }
                else
                {// Narrow triangle (or Narrow rhombus)
                        d = c + (a - c) * G;
                        //n1 = (d-b).yx * vec2(-1,1);// The dividing line is DB.
                        //f1 = dot(a-b, n1)*dot(u-b, n1);
                        f1 = cross(a-d,b-d).z*cross(u-d,b-d).z;
                        if(f1>0.){// In the triangle near point A.
                                //newa = d, newb = a, newc = b;                               
                                c=b; b=a; a=d;
                                type=2;
                        }else{
                                //newa = b, newb = c, newc = d;                                
                                a=b; b=c; c=d;
                                type=1;
                        }
                }
        }

        // Draw two sides of a triangle.
        float h = min(dline(a,c, u), dline(b,c,u));        

        o = vec4( smoothstep( .1 , 0., h/lca) );



        //return;

        // Draw background patterns
        if(o.x>.2)return;

        //G = .5;
        if(type==1){                
                h=abs(lca*.5-length(u-a));
        }else{                
                h=abs(lca*(1.-.5)-length(u-a));
        }

        if(type==2 || iMouse.x<iResolution.x*.55)
                h = cos(h*260.);

        o.xy += .2 * smoothstep(.02, 0.,h);

        // Draw green background
        o.y += float(type-1)*.3+.3;

        if(iMouse.y>iResolution.y*.55) o=o.yxzw;

}







